function prov(k, size = 40) {
  if (k === "cloudflare") return `<span class="prov-cf" style="width:${size}px;height:${size}px">${cfCloud()}</span>`;
  const [name, body] = PROV[k];
  return `<svg class="prov" viewBox="0 0 48 48" width="${size}" height="${size}" role="img" aria-label="${name}">${body}</svg>`;
}

