  sh: /(?<c>(?:^|(?<=\s))#[^\n]*)|(?<s>"(?:\\.|[^"\\])*"|'[^']*')|(?<v>\$\{[^}]*\}|\$[A-Za-z_]\w*)|(?<fl>(?<=\s)--?[A-Za-z][\w-]*)|(?<id>[A-Za-z_./][\w./:@-]*)|(?<ws>\s+)|(?<o>.)/g,
  sql: /(?<c>--[^\n]*)|(?<s>'(?:''|[^'])*')|(?<n>\b\d+(?:\.\d+)?\b)|(?<id>[A-Za-z_][\w.]*)|(?<ws>\s+)|(?<o>.)/g,
  html: /(?<c><!--[\s\S]*?-->)|(?<s>"[^"]*"|'[^']*')|(?<tg><\/?[\w-]+|\/?>)|(?<id>[A-Za-z_:][\w:.-]*)|(?<ws>\s+)|(?<o>.)/g,
  docker: /(?<c>#[^\n]*)|(?<s>"(?:\\.|[^"\\\n])*")|(?<n>\b\d+\b)|(?<id>[A-Za-z_][\w.:/-]*)|(?<ws>\s+)|(?<o>.)/g,
