// ---------------------------------------------------------------------
//  Demo context — timers/loops that are torn down on slide exit.
//  In export ("static") mode every sleep resolves instantly so demos
//  render their final state for HTML/PDF capture.
// ---------------------------------------------------------------------
function makeCtx(isStatic) {
  let alive = true;
  const timers = new Set(), disp = [], pend = [], kids = [];
  const ctx = {
    static: isStatic,
    startDelay: 1100,
    child() { const c = makeCtx(isStatic); c.startDelay = 150; disp.push(() => c.dispose()); kids.push(c); return c; },
    get alive() { return alive; },
    sleep(ms) {
      if (isStatic) return Promise.resolve();
      return new Promise((res) => {
        if (!alive) return;
        const t = setTimeout(() => { timers.delete(t); if (alive) res(); }, ms);
        timers.add(t);
      });
    },
    loop(fn, gap = 2200) {
      const run = (async () => {
        await ctx.sleep(ctx.startDelay);
        do {
          await fn();
          if (isStatic || !alive) break;
          await ctx.sleep(gap);
        } while (alive);
      })();
      pend.push(run.catch((e) => console.warn(e)));
      return run;
    },
    every(ms, fn) { if (isStatic) return; const t = setInterval(() => alive && fn(), ms); timers.add(t); },
    on(target, ev, fn, opts) { target.addEventListener(ev, fn, opts); disp.push(() => target.removeEventListener(ev, fn, opts)); },
    onDispose(fn) { disp.push(fn); },
    dispose() {
      alive = false;
      timers.forEach((t) => { clearTimeout(t); clearInterval(t); });
      timers.clear();
      disp.splice(0).forEach((f) => { try { f(); } catch {} });
    },
    async settled() {
      await new Promise((r) => setTimeout(r, 0));
      await Promise.all(pend);
      await Promise.all(kids.map((k) => k.settled()));
    },
  };
  return ctx;
}

async function typeText(ctx, el, text, cps = 45) {
  if (ctx.static) { el.textContent = text; return; }
  el.textContent = "";
  for (let i = 0; i < text.length; i++) {
    el.textContent = text.slice(0, i + 1);
    await ctx.sleep(1000 / cps);
  }
}
async function countTo(ctx, el, from, to, ms = 900, f = fmtNum) {
  if (ctx.static) { el.textContent = f(to); return; }
  const t0 = performance.now();
  return new Promise((res) => {
    const step = (t) => {
      if (!ctx.alive) return;
      const p = Math.min(1, (t - t0) / ms);
      el.textContent = f(from + (to - from) * easeInOut(p));
      p < 1 ? requestAnimationFrame(step) : res();
    };
    requestAnimationFrame(step);
  });
}

