// Node/edge diagram with animated packets.
function flow(ctx, { w, h: hh, nodes, edges = [], cls = "" }) {
  const wrap = h("div", { class: `flow ${cls}`, style: `width:${w}px;height:${hh}px` });
  const svg = S("svg", { class: "flow-svg", width: w, height: hh, viewBox: `0 0 ${w} ${hh}` });
  wrap.append(svg);
  const N = {}, E = {};
  for (const n of nodes) {
    const el = h("div", { class: `fnode ${n.cls || ""}`, style: `left:${n.x}px;top:${n.y}px;width:${n.w}px;height:${n.h}px;${n.style || ""}` },
      n.logo ? h("span", { class: "fn-logo", html: n.logo }) : n.icon ? h("span", { class: "fn-ic", html: icoSvg(n.icon) }) : null,
      n.label != null || n.sub != null ? h("div", { class: "fn-tx" },
        n.label != null ? h("div", { class: "fn-l", html: fmt(n.label) }) : null,
        n.sub != null ? h("div", { class: "fn-s", html: fmt(n.sub) }) : null) : null,
      n.badge ? h("span", { class: "fn-b", html: fmt(n.badge) }) : null,
      n.body || null);
    if (n.delay != null) A(el, n.delay);
    N[n.id] = { ...n, el };
    wrap.append(el);
  }
  const anchor = (n, side) => {
    switch (side) {
      case "r": return [n.x + n.w, n.y + n.h / 2];
      case "l": return [n.x, n.y + n.h / 2];
      case "t": return [n.x + n.w / 2, n.y];
      case "b": return [n.x + n.w / 2, n.y + n.h];
      default: return [n.x + n.w / 2, n.y + n.h / 2];
    }
  };
  for (const e of edges) {
    let d = e.d;
    if (!d) {
      const a = N[e.from], b = N[e.to];
      const fs = e.fs || "r", ts = e.ts || "l";
      const [x1, y1] = anchor(a, fs), [x2, y2] = anchor(b, ts);
      if (fs === "c" || ts === "c" || e.straight) d = `M${x1} ${y1} L${x2} ${y2}`;
      else {
        const k = e.k ?? 0.5;
        const c1 = fs === "r" || fs === "l" ? [x1 + (x2 - x1) * k, y1] : [x1, y1 + (y2 - y1) * k];
        const c2 = ts === "l" || ts === "r" ? [x2 - (x2 - x1) * k, y2] : [x2, y2 - (y2 - y1) * k];
        d = `M${x1} ${y1} C${c1[0]} ${c1[1]} ${c2[0]} ${c2[1]} ${x2} ${y2}`;
      }
    }
    const p = S("path", { d, class: `fedge ${e.cls || ""}` });
    svg.append(p);
    if (e.label) {
      const mid = e.lp || null;
      const t = S("text", { class: "fedge-l", "text-anchor": "middle" }, e.label);
      svg.append(t);
      requestAnimationFrame(() => {
        try {
          const L = p.getTotalLength(); const pt = mid ? { x: mid[0], y: mid[1] } : p.getPointAtLength(L / 2);
          t.setAttribute("x", pt.x); t.setAttribute("y", pt.y - 10);
        } catch {}
      });
    }
    E[e.id || `${e.from}-${e.to}`] = { el: p, lit: 0 };
  }
  function pulse(id, o = {}) {
    return new Promise((res) => {
      const e = E[id];
      if (ctx.static || !e) return res();
      const path = e.el;
      let L = 0;
      try { L = path.getTotalLength(); } catch { return res(); }
      // Position the dot at its start point before it is added, or it flashes at (0,0) for a frame.
      const p0 = path.getPointAtLength(o.rev ? L : 0);
      const c = S("circle", { r: o.r || 6, cx: p0.x, cy: p0.y, class: `pkt ${o.cls || ""}` });
      svg.append(c);
      e.lit++; path.classList.add("lit");
      const t0 = performance.now(), dur = o.dur || 900;
      const step = (t) => {
        if (!ctx.alive) { c.remove(); return; }
        const p = Math.min(1, (t - t0) / dur), ep = easeInOut(p);
        const pt = path.getPointAtLength((o.rev ? 1 - ep : ep) * L);
        c.setAttribute("cx", pt.x); c.setAttribute("cy", pt.y);
        if (p < 1) requestAnimationFrame(step);
        else { c.remove(); if (--e.lit <= 0) path.classList.remove("lit"); res(); }
      };
      requestAnimationFrame(step);
    });
  }
  function set(id, st = {}) {
    const n = N[id]; if (!n) return;
    if ("state" in st) { n.el.classList.remove("on", "ok", "err", "warn", "dim"); if (st.state) n.el.classList.add(st.state); }
    if ("sub" in st) { const s = n.el.querySelector(".fn-s"); if (s) s.innerHTML = fmt(st.sub); }
    if ("label" in st) { const s = n.el.querySelector(".fn-l"); if (s) s.innerHTML = fmt(st.label); }
    if ("badge" in st) { const s = n.el.querySelector(".fn-b"); if (s) { s.innerHTML = fmt(st.badge); s.style.display = st.badge ? "" : "none"; } }
  }
  async function flash(id, state = "on", ms = 700) { set(id, { state }); await ctx.sleep(ms); if (ctx.alive) set(id, { state: "" }); }
  return { el: wrap, N, E, pulse, set, flash, svg };
}

