C.boardTs = `import { DurableObject } from "cloudflare:workers";

export class Board extends DurableObject {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.storage.sql.exec("CREATE TABLE IF NOT EXISTS strokes (data TEXT)");
  }

  async fetch(req: Request) {
    const [client, server] = Object.values(new WebSocketPair());
    this.ctx.acceptWebSocket(server);              // hibernatable socket
    for (const row of this.ctx.storage.sql.exec("SELECT data FROM strokes"))
      server.send(row.data as string);             // late joiners catch up
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, msg: string) {
    this.ctx.storage.sql.exec("INSERT INTO strokes VALUES (?)", msg);
    for (const peer of this.ctx.getWebSockets())
      if (peer !== ws) peer.send(msg);             // fan out
  }
}`;
