C.r2Ts = `export default {
  async fetch(req: Request, env: Env) {
    const key = new URL(req.url).pathname.slice(1);

    if (req.method === "PUT") {
      await env.MEDIA.put(key, req.body, {
        httpMetadata: { contentType: req.headers.get("content-type") ?? undefined },
      });
      return new Response(\`stored \${key}\`, { status: 201 });
    }

    const obj = await env.MEDIA.get(key, { range: req.headers });
    if (!obj) return new Response("not found", { status: 404 });

    const headers = new Headers();
    obj.writeHttpMetadata(headers);
    headers.set("etag", obj.httpEtag);
    return new Response(obj.body, { headers });
  },
};`;
