C.k2Ts = `const encoder = new TextEncoder();

export default {
  async fetch(req: Request, env: Env) {
    const order = await req.json<Order>();

    const res = await env.ORDERS.send([{
      content: encoder.encode(JSON.stringify(order)),
      headers: { "event-type": "order.created" },
    }]);

    if (!res.success) {
      // delivery is at-least-once: retryable errors are safe to retry
      const status = res.error.retryable ? 503 : 400;
      return new Response(res.error.message, { status });
    }
    return new Response("accepted", { status: 202 });
  },
};`;
