C.agentTs = `import { Agent, callable, routeAgentRequest } from "agents";

type State = { tasks: { title: string; done: boolean }[] };

export class TaskAgent extends Agent<Env, State> {
  initialState: State = { tasks: [] };

  @callable() addTask(title: string) {
    this.setState({ tasks: [...this.state.tasks, { title, done: false }] });
  }

  @callable() async complete(i: number) {
    const tasks = this.state.tasks.map((t, j) => (j === i ? { ...t, done: true } : t));
    this.setState({ tasks });                               // syncs to every client
    await this.schedule(3600, "remind", { task: i + 1 });   // durable timer
  }

  async remind({ task }: { task: number }) {
    this.broadcast(JSON.stringify({ type: "reminder", task }));
  }
}

export default {
  async fetch(req: Request, env: Env) {
    return (await routeAgentRequest(req, env)) ?? new Response("Not found", { status: 404 });
  },
};`;
