C.mcpTs = `import { McpAgent } from "agents/mcp";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

export class TodoMCP extends McpAgent<Env> {
  server = new McpServer({ name: "todos", version: "1.0.0" });

  async init() {
    this.server.tool("add_todo", { title: z.string() }, async ({ title }) => {
      const { meta } = await this.env.DB
        .prepare("INSERT INTO todos (title) VALUES (?)").bind(title).run();
      return { content: [{ type: "text", text: \`Added #\${meta.last_row_id}\` }] };
    });

    this.server.tool("list_todos", {}, async () => {
      const { results } = await this.env.DB.prepare("SELECT * FROM todos").all();
      return { content: [{ type: "text", text: JSON.stringify(results) }] };
    });
  }
}

export default TodoMCP.serve("/mcp");   // Streamable HTTP endpoint`;
